   227|
   228|/**
   229| * In-memory mirror so the queue/worker keep functioning even when Supabase is
   230| * not configured (local dev / tests) and to avoid a read-modify-write race
   231| * between the enqueue call and the async drain.
   232| */
   233|let memoryQueue: QueueDoc | null = null;
   234|let memoryLedger: LedgerDoc | null = null;
   235|let draining = false;
   236|
   237|/** Active job callbacks for cancel signaling. */
   238|const activeJobControllers = new Map<string, { cancelled: boolean }>();
   239|
   240|async function loadQueue(): Promise<QueueDoc> {
   241|  const durable = isDurableStoreConfigured();
   242|  if (!durable) {
   243|    if (!memoryQueue) memoryQueue = emptyQueue(false);
   244|    return memoryQueue;
   245|  }
   246|  try {
   247|    const doc = await readDurableJson<QueueDoc>(QUEUE_FILE, emptyQueue(true));
   248|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   249|  } catch {
   250|    if (!memoryQueue) memoryQueue = emptyQueue(false);
   251|    return memoryQueue;
   252|  }
   253|}
