   295|// ── GitHub side-branch ledger persistence (no Supabase service key needed) ──
   296|// The ledger is committed to a NON-deploy branch so Render autoDeploy (which
   297|// watches main) never fires from a ledger write. No secrets are stored.
   298|
   299|const LEDGER_GITHUB_BRANCH = 'ivx-proof-ledger';
   300|const DEFAULT_LEDGER_REPO = 'ibb142/rork-global-real-estate-invest';
   301|
   302|function ledgerGithubToken(): string {
   303|  return typeof process.env.GITHUB_TOKEN === 'string' ? process.env.GITHUB_TOKEN.trim() : '';
   304|}
   305|
   306|function ledgerGithubRepo(): string {
   307|  const raw = typeof process.env.GITHUB_REPO === 'string' ? process.env.GITHUB_REPO.trim() : '';
   308|  const match = raw.match(/([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+?)(?:\.git)?$/);
   309|  if (match && match[1].includes('/')) return match[1];
   310|  return DEFAULT_LEDGER_REPO;
   311|}
   312|
   313|function ledgerGithubHeaders(): Record<string, string> {
   314|  return {
   315|    Authorization: `Bearer ${ledgerGithubToken()}`,
   316|    Accept: 'application/vnd.github+json',
   317|    'Content-Type': 'application/json',
   318|  };
