   321|async function githubLedgerRead(): Promise<LedgerDoc | null> {
   322|  const token = ledgerGithubToken();
   323|  if (!token) return null;
   324|  try {
   325|    const res = await fetch(
   326|      `https://api.github.com/repos/${ledgerGithubRepo()}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   327|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   328|    );
