   330|    const data = await res.json() as { content?: string };
   331|    if (!data.content) return null;
   332|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   333|    const doc = JSON.parse(decoded) as LedgerDoc;
   334|    if (!Array.isArray(doc.entries)) return null;
   335|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   336|  } catch {
