   341|async function githubEnsureLedgerBranch(): Promise<boolean> {
   342|  const repo = ledgerGithubRepo();
   343|  try {
   344|    const refRes = await fetch(
   345|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   346|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   347|    );
   348|    if (refRes.ok) return true;
   349|    const mainRes = await fetch(
   350|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   351|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   352|    );
   353|    if (!mainRes.ok) return false;
   354|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   355|    const baseSha = mainData.object?.sha;
   356|    if (!baseSha) return false;
   357|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   358|      method: 'POST',
   359|      headers: ledgerGithubHeaders(),
   360|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   361|      signal: AbortSignal.timeout(10000),
   362|    });
   363|    return createRes.ok;
   364|  } catch {
   365|    return false;
   366|  }
