   369|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   370|  const token = ledgerGithubToken();
   371|  if (!token) return false;
   372|  const repo = ledgerGithubRepo();
   373|  try {
   374|    if (!(await githubEnsureLedgerBranch())) return false;
   375|    let existingSha: string | undefined;
   376|    const currentRes = await fetch(
   377|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   378|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   379|    );
   380|    if (currentRes.ok) {
   381|      const current = await currentRes.json() as { sha?: string };
   382|      existingSha = current.sha;
   383|    }
   384|    const putRes = await fetch(
   385|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   386|      {
   387|        method: 'PUT',
   388|        headers: ledgerGithubHeaders(),
   389|        body: JSON.stringify({
   390|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   391|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   392|          branch: LEDGER_GITHUB_BRANCH,
   393|          ...(existingSha ? { sha: existingSha } : {}),
   394|        }),
   395|        signal: AbortSignal.timeout(15000),
   396|      },
   397|    );
   398|    return putRes.ok;
   399|  } catch {
   400|    return false;
   401|  }
   402|}
   403|
   404|async function appendLedger(result: IVXWorkerJobResult): Promise<void> {
   405|  const current = await loadLedger();
   406|  const entries = [result, ...current.entries.filter((e) => e.jobId !== result.jobId)].slice(0, MAX_LEDGER_RETAINED);
   407|  const doc: LedgerDoc = {
   408|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   409|    durable: isDurableStoreConfigured(),
   410|    updatedAt: nowIso(),
   411|    entries,
   412|  };
   413|  memoryLedger = doc;
   414|  if (isDurableStoreConfigured()) {
   415|    try {
   416|      await writeDurableJson(LEDGER_FILE, doc);
   417|      await appendDurableEvent(LEDGER_FILE, { type: 'proof_ledger_entry', ...result } as Record<string, unknown>);
   418|    } catch {
   419|      // Durable write failed — in-memory ledger still holds the entry.
   420|    }
   421|  } else {
   422|    // No Supabase service key in this runtime — persist to the GitHub side
   423|    // branch so proof survives Render's diskless deploy restarts.
   424|    await githubLedgerWrite({ ...doc, durable: true });
   425|  }
   426|}
   427|
   428|/**
   429| * Archive an externally-produced deployment proof (e.g. from the chat
   430| * deployment brain's /deploy-pipeline) into the same durable proof ledger the
   431| * worker writes, so /senior-proof and /senior-ledger surface it.
   432| */
   433|export async function archiveDeploymentProofToLedger(entry: IVXWorkerJobResult): Promise<boolean> {
   434|  try {
   435|    await appendLedger(entry);
   436|    return true;
   437|  } catch {
   438|    return false;
   439|  }
   440|}
   441|
   442|/**
   443| * Derive a secret-safe proof summary from a read-only inspection proof. The
   444| * result shape is the same `IVXWorkerJobResult` the durable ledger stores for
   445| * developer_executor jobs, so /senior-proof and /senior-ledger surface it the
   446| * same way. All mutation flags are forced false (read-only mode never edits,
   447| * commits, pushes, or deploys).
   448| */
   449|export function summarizeReadOnlyInspectionProof(
   450|  jobId: string,
   451|  proof: IVXReadOnlyInspectionProof,
   452|): IVXWorkerJobResult {
   453|  const finalStatus: IVXWorkerJobResult['finalStatus'] = proof.finalStatus === 'COMPLETED'
   454|    ? 'COMPLETE'
   455|    : proof.finalStatus === 'BLOCKED'
   456|      ? 'BLOCKED'
   457|      : 'FAILED';
   458|  return {
   459|    jobId,
   460|    goal: proof.goal.slice(0, 280),
   461|    ok: proof.finalStatus === 'COMPLETED',
   462|    endToEndProductionComplete: false,
   463|    changedFiles: [],
   464|    testsRun: proof.commandsRun.some((cmd) => cmd.kind === 'run_tests'),
   465|    testsPassed: proof.commandsRun.some((cmd) => cmd.kind === 'run_tests') && proof.commandsRun.filter((cmd) => cmd.kind === 'run_tests').every((cmd) => cmd.ok),
   466|    typecheckRun: proof.commandsRun.some((cmd) => cmd.kind === 'typecheck'),
   467|    buildRun: false,
   468|    commitCreated: false,
   469|    commitSha: null,
   470|    commitUrl: null,
   471|    pushed: false,
   472|    branch: null,
   473|    deployId: null,
   474|    deployStatus: null,
   475|    deployVerified: false,
   476|    liveCommit: null,
   477|    commitMatch: false,
   478|    healthOk: false,
   479|    healthStatus: null,
   480|    versionEndpoint: null,
   481|    generatedFeatureSlug: null,
   482|    auditFiles: { json: '', jsonl: '' },
   483|    finalStatus,
   484|    error: proof.error,
   485|    durable: isDurableStoreConfigured(),
   486|    generatedAt: proof.generatedAt,
   487|  };
   488|}
