   490|/**
   491| * Derive a secret-safe proof summary from a full senior-developer run proof and
   492| * the optional deploy-match verification.
   493| */
   494|export function summarizeProof(
   495|  jobId: string,
   496|  proof: IVXSeniorDeveloperRunProof,
   497|  match: Awaited<ReturnType<typeof verifyLiveCommitMatch>> | null,
   498|): IVXWorkerJobResult {
   499|  const validations = proof.validations;
   500|  const testValidation = validations.find((v) => /test|import-smoke/i.test(v.command)) ?? null;
   501|  const typecheckValidation = validations.find((v) => /tsc|typecheck|noEmit/i.test(v.command)) ?? null;
   502|  const commitSha = proof.gitDeployOperator.github.commitSha;
   503|  const commitCreated = Boolean(commitSha) && proof.gitDeployOperator.github.commitAttempted;
   504|  const deployId = proof.gitDeployOperator.render.deployId;
   505|  const deployStatus = proof.gitDeployOperator.render.deployStatus;
   506|  const healthOk = proof.productionVerification.ok;
   507|
   508|  const finalStatus: IVXWorkerJobResult['finalStatus'] = proof.endToEndProductionComplete
   509|    ? 'COMPLETE'
   510|    : proof.ok
   511|      ? 'LOCAL_ONLY'
   512|      : proof.gitDeployOperator.status === 'blocked_missing_credentials'
   513|        || proof.gitDeployOperator.status === 'ready_owner_approval_required'
   514|        ? 'BLOCKED'
   515|        : 'FAILED';
   516|
   517|  return {
   518|    jobId,
   519|    goal: proof.goal.slice(0, 280),
   520|    ok: proof.ok,
   521|    endToEndProductionComplete: proof.endToEndProductionComplete,
   522|    changedFiles: proof.changedFiles.slice(0, 25),
   523|    testsRun: testValidation !== null,
   524|    testsPassed: validations.length > 0 && validations.every((v) => v.ok),
   525|    typecheckRun: typecheckValidation !== null,
   526|    buildRun: validations.length > 0,
   527|    commitCreated,
   528|    commitSha,
   529|    commitUrl: proof.gitDeployOperator.github.commitUrl,
   530|    pushed: commitCreated,
   531|    branch: proof.gitDeployOperator.github.branch,
   532|    deployId,
   533|    deployStatus,
   534|    deployVerified: match?.match ?? false,
   535|    liveCommit: match?.liveCommit ?? null,
   536|    commitMatch: match?.match ?? false,
