import { runIVXAutonomousCoder } from './backend/services/ivx-autonomous-coder';
import { PILOT_LABEL, PILOT_LABEL_TARGET } from './backend/services/ivx-autonomous-coder-pilot';
import path from 'node:path';
import os from 'node:os';
import { writeFile, readFile, mkdir } from 'node:fs/promises';

const root = path.join(os.tmpdir(), `ivx-ac-debug-${Date.now()}`);
await mkdir(path.join(root, 'backend/services'), { recursive: true });
const pilotContent = `export const PILOT_LABEL = '${PILOT_LABEL}';\nexport const PILOT_LABEL_TARGET = '${PILOT_LABEL_TARGET}';\n`;
await writeFile(path.join(root, 'backend/services/ivx-autonomous-coder-pilot.ts'), pilotContent, 'utf8');

const fileWriter = async (rel: string, content: string) => {
  await mkdir(path.dirname(path.join(root, rel)), { recursive: true });
  await writeFile(path.join(root, rel), content, 'utf8');
};
const fileReader = async (rel: string) => readFile(path.join(root, rel), 'utf8');

const llmCaller = async () => JSON.stringify({
  rootCause: 'test',
  technicalPlan: 'test',
  operations: [{
    path: 'backend/services/ivx-autonomous-coder-pilot.ts',
    kind: 'replace_exact',
    oldText: `export const PILOT_LABEL = '${PILOT_LABEL}';`,
    newText: `export const PILOT_LABEL = '${PILOT_LABEL_TARGET}';`,
    reason: 'test',
  }],
});

const testRunner = async (_cwd: string, command: string) => ({
  command, ok: true, exitCode: 0, stdoutTail: '', stderrTail: '', durationMs: 1,
});

const commitFn = async () => ({ commitSha: 'test-sha', commitUrl: 'url', branch: 'main' });

const proof = await runIVXAutonomousCoder({
  taskId: 'debug-001',
  goal: `Change pilot label from ${PILOT_LABEL} to ${PILOT_LABEL_TARGET}.`,
  executionMode: 'code_change',
  ownerId: 'test',
  approvalPolicy: 'owner_gated',
  projectRoot: root,
  fileWriter,
  fileReader,
  llmCaller,
  testRunner: testRunner as any,
  commitFn: commitFn as any,
});

console.log('finalStatus:', proof.finalStatus);
console.log('error:', proof.error);
console.log('iterations.length:', proof.iterations.length);
console.log('iterationCount:', proof.iterationCount);
console.log('iterations[0]:', JSON.stringify(proof.iterations[0], null, 2));
console.log('testsPassed:', proof.testsPassed);
console.log('typecheckPassed:', proof.typecheckPassed);
console.log('filesChanged:', proof.filesChanged);
console.log('commitSha:', proof.commitSha);

// Check the file
const finalContent = await fileReader('backend/services/ivx-autonomous-coder-pilot.ts');
console.log('final file content:', finalContent);
EOF
