// Commit the 5 autonomous coder files via the owner-gated github_commit_file API.
const { gzipSync } = require('node:zlib');
const { readFileSync } = require('node:fs');
const path = require('node:path');

const OWNER_AT_PATH = '/tmp/owner_at';
const API_BASE = 'https://api.ivxholding.com';

function ownerToken() {
  return readFileSync(OWNER_AT_PATH, 'utf8').trim();
}

function fileToGzipBase64(absPath) {
  const content = readFileSync(absPath);
  const gz = gzipSync(content);
  return gz.toString('base64');
}

const FILES = [
  { path: 'backend/services/ivx-autonomous-coder-pilot.ts', file: 'backend/services/ivx-autonomous-coder-pilot.ts', message: 'feat(ivx-autonomous-coder): add pilot sentinel for the first controlled autonomous coding test' },
  { path: 'backend/services/ivx-autonomous-coder.ts', file: 'backend/services/ivx-autonomous-coder.ts', message: 'feat(ivx-autonomous-coder): implement the real autonomous coding loop engine (inspect, plan, patch, test, revise, commit, deploy-gated)' },
  { path: 'backend/ivx-autonomous-coder.test.ts', file: 'backend/ivx-autonomous-coder.test.ts', message: 'test(ivx-autonomous-coder): 10 regression tests for the autonomous coding loop (commit, block, revise, max-iter, deploy-gate, deploy-approved, read-only, answer format)' },
  { path: 'backend/services/ivx-senior-developer-worker.ts', file: 'backend/services/ivx-senior-developer-worker.ts', message: 'feat(ivx-worker): wire autonomous coder into the worker queue as code_change/deploy execution mode with phase mapping + proof summarizer' },
  { path: 'backend/api/ivx-owner-ai.ts', file: 'backend/api/ivx-owner-ai.ts', message: 'feat(ivx-owner-ai): route autonomous-coder prompts through the worker queue with bounded warmup + honest live-progress + terminal evidence' },
];

async function commitOne(entry) {
  const absPath = path.join('/home/user/rork-app', entry.file);
  const contentEncoding = 'gzip-base64';
  const content = fileToGzipBase64(absPath);
  const body = {
    action: 'github_commit_file',
    input: {
      path: entry.path,
      content,
      contentEncoding,
      message: entry.message,
    },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  console.log(`Committing ${entry.path} (${content.length} base64 chars)...`);
  const res = await fetch(`${API_BASE}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${ownerToken()}`,
    },
    body: JSON.stringify(body),
  });
