function fileToGzipBase64(absPath) {
  return gzipSync(readFileSync(absPath)).toString('base64');
}

const FILES = [
  { path: 'backend/services/ivx-autonomous-coder.ts', file: 'backend/services/ivx-autonomous-coder.ts', message: 'fix(ivx-autonomous-coder): resolve bun→node runtime fallback for Render (bun test → node --test, bun x tsc → npx tsc) so tests/typecheck run on the node+tsx production container instead of ENOENT-blocking the pilot' },
  { path: 'backend/api/ivx-owner-ai.ts', file: 'backend/api/ivx-owner-ai.ts', message: 'fix(ivx-owner-ai): autonomous coder deploy-negation routing — "do not deploy" / "without deploying" must NOT trigger deploy execution mode (only affirmative deploy/production/live triggers it)' },
];

async function commitOne(entry) {
  const absPath = path.join('/home/user/rork-app', entry.file);
  const content = fileToGzipBase64(absPath);
  const body = {
    action: 'github_commit_file',
    input: { path: entry.path, content, contentEncoding: 'gzip-base64', message: entry.message },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  console.log(`Committing ${entry.path}...`);
  const res = await fetch(`${API_BASE}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ownerToken}` },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = { raw: text.slice(0, 500) }; }
  const commitSha = json?.result?.commitSha;
  console.log(`  HTTP ${res.status} commitSha=${commitSha ?? '(none)'}`);
  return { ok: res.ok, commitSha };
}

(async () => {
  const results = [];
  for (const entry of FILES) {
    const r = await commitOne(entry);
    results.push(r);
    await new Promise((resolve) => setTimeout(resolve, 800));
  }
  const allOk = results.every((r) => r.ok);
  console.log(`All committed: ${allOk}`);
  process.exit(allOk ? 0 : 1);
})();
