```js
const result = summarizeAutonomousCoderProof(job.jobId, coderProof);
const status = result.finalStatus === 'COMPLETE' ? 'completed' : result.finalStatus === 'BLOCKED' ? 'blocked' : 'failed';
await updateJob(job.jobId, { status, stage: finalStage, ..., result, error: result.error });
