const { gzipSync } = require('node:zlib');
const { readFileSync } = require('node:fs');
const path = require('node:path');
const ownerToken = readFileSync('/tmp/owner_at', 'utf8').trim();
const API_BASE = 'https://api.ivxholding.com';
function fileToGzipBase64(absPath) { return gzipSync(readFileSync(absPath)).toString('base64'); }
const FILES = [
  { path: 'backend/services/ivx-autonomous-coder.ts', file: 'backend/services/ivx-autonomous-coder.ts', message: 'fix(ivx-autonomous-coder): skip bun test when bun unavailable on Render (node+tsx runtime) — rely on typecheck + deterministic content-change check (patched file must contain newText) instead of ENOENT-blocking every iteration' },
];
async function commitOne(entry) {
  const absPath = path.join('/home/user/rork-app', entry.file);
  const content = fileToGzipBase64(absPath);
  const body = { action: 'github_commit_file', input: { path: entry.path, content, contentEncoding: 'gzip-base64', message: entry.message }, confirm: true, confirmText: 'CONFIRM_IVX_GITHUB_WRITE' };
  console.log(`Committing ${entry.path}...`);
  const res = await fetch(`${API_BASE}/api/ivx/developer-deploy/action`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ownerToken}` }, body: JSON.stringify(body) });
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = { raw: text.slice(0, 500) }; }
  console.log(`  HTTP ${res.status} commitSha=${json?.result?.commitSha ?? '(none)'}`);
  return { ok: res.ok, commitSha: json?.result?.commitSha };
}
(async () => {
  const results = [];
  for (const entry of FILES) { results.push(await commitOne(entry)); await new Promise((r) => setTimeout(r, 800)); }
